-- ══════════════════════════════════════════════════════════════════
-- 103 · Recuperar los 2 decimales de los partes de JotForm (10/11/2026)
--
-- CORRER DESPUÉS DEL 102 (si no, la base los vuelve a redondear: el
-- script lo controla y se frena).
--
-- La base guardaba el horómetro con 1 decimal, así que los partes de
-- JotForm que traían 2 (ej. 1757,54) quedaron redondeados (1757,5).
-- Este script vuelve a poner el valor original, sacado de la hoja de
-- JotForm (DATA REGISTRO PARTE DIARIO EQUIPOS, exportada el 04/11/2026):
-- 1270 partes del 2025-04-04 al 2026-11-03.
--
-- Solo cambia un valor si:
--   · el parte vino de JotForm (origen = 'jotform', mismo submission id),
--   · nadie lo corrigió a mano en la app (historial de ediciones), y
--   · lo que está guardado es exactamente el original redondeado a 1
--     decimal (si ya tiene otro valor, se deja como está).
-- Se cambian horómetro inicial, final y horas reportadas; las horas por
-- horómetro se recalculan solas.
--
-- Los disparadores de partes se apagan solo durante esta corrección (no
-- es una carga nueva: no tiene que mover el horómetro de la Flota ni
-- evaluar saltos ni llenar el historial de ediciones) y se vuelven a
-- prender al final, dentro de la misma transacción.
--
-- Los partes posteriores al 04/11 los corrige sola la sincronización con
-- JotForm en su próxima corrida (últimos 60 días).
-- Los certificados de máquinas ya guardados no cambian (cada uno guarda
-- sus cantidades); al tocar «↻ Partes» en un borrador toma las horas nuevas.
-- ══════════════════════════════════════════════════════════════════

begin;

do $$
begin
  if (select numeric_scale from information_schema.columns
       where table_schema = 'public' and table_name = 'partes' and column_name = 'horometro_inicial') <> 2 then
    raise exception 'Primero hay que correr 102_horometro_dos_decimales.sql';
  end if;
end
$$;

create temp table _jf_dec (submission_id text primary key, hi numeric(12,2), hf numeric(12,2), hr numeric(8,2)) on commit drop;

create temp table _jf_antes on commit drop as
select p.id, p.horometro_inicial, p.horometro_final, p.horas_horometro_reportada, p.horas_horometro
  from partes p join _jf_dec d on d.submission_id = p.submission_id
 where p.origen = 'jotform'
   and not exists (select 1 from log_ediciones l where l.parte_id = p.id and l.usuario_id is not null);

alter table public.partes disable trigger user;

update partes p set
  horometro_inicial         = case when d.hi is not null and p.horometro_inicial         = round(d.hi, 1) then d.hi else p.horometro_inicial end,
  horometro_final           = case when d.hf is not null and p.horometro_final           = round(d.hf, 1) then d.hf else p.horometro_final end,
  horas_horometro_reportada = case when d.hr is not null and p.horas_horometro_reportada = round(d.hr, 1) then d.hr else p.horas_horometro_reportada end
  from _jf_dec d, _jf_antes a
 where a.id = p.id and d.submission_id = p.submission_id
   and ((d.hi is not null and p.horometro_inicial = round(d.hi, 1) and p.horometro_inicial <> d.hi)
     or (d.hf is not null and p.horometro_final = round(d.hf, 1) and p.horometro_final <> d.hf)
     or (d.hr is not null and p.horas_horometro_reportada = round(d.hr, 1) and p.horas_horometro_reportada <> d.hr));

alter table public.partes enable trigger user;

-- ── Resultado ──
select
  (select count(*) from _jf_dec)                                                   as en_jotform_con_2_decimales,
  (select count(*) from _jf_antes)                                                 as encontrados_sin_edicion_manual,
  (select count(*) from partes p join _jf_antes a using (id)
    where p.horometro_inicial is distinct from a.horometro_inicial
       or p.horometro_final is distinct from a.horometro_final
       or p.horas_horometro_reportada is distinct from a.horas_horometro_reportada) as partes_corregidos,
  (select round(sum(p.horas_horometro - a.horas_horometro), 2) from partes p join _jf_antes a using (id)) as diferencia_total_horas,
  (select count(*) from pg_trigger where tgrelid = 'public.partes'::regclass and not tgisinternal and tgenabled = 'D') as disparadores_apagados_deberia_0;

commit;
